WITH incoming AS (SELECT o.* FROM jsonb_to_recordset('[{"project":"c3b59b93-0b56-4d5c-a9b3-f59a31bf36b7","folder":"topic-7","first_shipped_on":"2026-09-01","window_start":"2026-09-14T00:00:00Z","window_end":"2026-10-14T00:00:00Z","loads":12,"load_sessions":4,"loaded_turns":9,"judged_turns":8,"corrected_turns":4,"base_judged_turns":40,"base_corrected_turns":8,"retired_at":null,"retired_reason":null}]'::jsonb) AS o(project uuid, folder text, first_shipped_on date, window_start timestamptz, window_end timestamptz, loads integer, load_sessions integer, loaded_turns integer, judged_turns integer, corrected_turns integer, base_judged_turns integer, base_corrected_turns integer, retired_at timestamptz, retired_reason text)) INSERT INTO memory.skill_live_outcomes (project_id, folder, first_shipped_on, window_start, window_end, loads, load_sessions, loaded_turns, judged_turns, corrected_turns, base_judged_turns, base_corrected_turns, retired_at, retired_reason) SELECT p.id, i.folder, i.first_shipped_on, i.window_start, i.window_end, i.loads, i.load_sessions, i.loaded_turns, i.judged_turns, i.corrected_turns, i.base_judged_turns, i.base_corrected_turns, i.retired_at, i.retired_reason FROM incoming i JOIN projects.projects p ON p.project_uuid = i.project ON CONFLICT (project_id, folder, first_shipped_on) DO UPDATE SET window_start = EXCLUDED.window_start, window_end = EXCLUDED.window_end, loads = EXCLUDED.loads, load_sessions = EXCLUDED.load_sessions, loaded_turns = EXCLUDED.loaded_turns, judged_turns = EXCLUDED.judged_turns, corrected_turns = EXCLUDED.corrected_turns, base_judged_turns = EXCLUDED.base_judged_turns, base_corrected_turns = EXCLUDED.base_corrected_turns, retired_at = COALESCE(memory.skill_live_outcomes.retired_at, EXCLUDED.retired_at), retired_reason = COALESCE(memory.skill_live_outcomes.retired_reason, EXCLUDED.retired_reason), measured_at = now()
